styles.css:
.app-background::after { content: ""; position: absolute; inset: 0; pointer-events: none; opacity: .05; background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='160' height='160'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='2' stitchTiles='stitch'/><feColorMatrix values='0 0 0 0 .5  0 0 0 0 .5  0 0 0 0 .5  0 0 0 .55 0'/></filter><rect width='100%' height='100%' filter='url(%23n)'/></svg>"); }
.aicode-tooltip, .context-menu, .quick-input { backdrop-filter: blur(18px) saturate(1.4); -webkit-backdrop-filter: blur(18px) saturate(1.4); }
[data-part="sideBar"], [data-part="secondarySideBar"], [data-part="activityBar"], [data-part="panel"], [data-part="editor"] { border-color: color-mix(in srgb, var(--aicode-foreground) 10%, transparent) !important; }
